mapper.select:
( SELECT B_MSG_KEY, LOGIN_ID, USER_ID, TITLE, MSG, REPLACE( REPLACE( REPLACE( CONVERT(VARCHAR(19), IN_TIME, 120), '-', ''), ':', ''), ' ', '') AS IN_TIME, REPLACE( REPLACE( REPLACE( CONVERT(VARCHAR(19), REQ_TIME, 120), '-', ''), ':', ''), ' ', '') AS REQ_TIME, CNT, STATUS, SVC_TYPE, B_SEQ FROM T_BROADCAST_MSG WHERE REPLACE(REPLACE(REPLACE(CONVERT(VARCHAR(19), REQ_TIME, 120), '-', ''), ':', ''), ' ', '') >= #{startTime} AND REPLACE(REPLACE(REPLACE(CONVERT(VARCHAR(19), REQ_TIME, 120), '-', ''), ':', ''), ' ', '') <= #{endTime}
AND TITLE LIKE CONCAT('%', #{bulkTitle}, '%')
) ORDER BY B_SEQ DESC
OFFSET #{skip} ROWS FETCH NEXT #{take} ROWS ONLY

SELECT COUNT(*) FROM (			
	SELECT 1 AS CNT
	FROM T_BROADCAST_MSG
	WHERE REPLACE(REPLACE(REPLACE(CONVERT(VARCHAR(19), REQ_TIME, 120), '-', ''), ':', ''), ' ', '') >= #{startTime}
		AND REPLACE(REPLACE(REPLACE(CONVERT(VARCHAR(19), REQ_TIME, 120), '-', ''), ':', ''), ' ', '') <= #{endTime}

		AND TITLE LIKE CONCAT('%', #{bulkTitle}, '%')

) TOTAL

choose.when:
SELECT COUNT(CASE WHEN TRAN_STATUS = 1 THEN 1 END) AS cntStanby, COUNT(CASE WHEN TRAN_STATUS IN (2, 3) THEN 1 END) AS cntTran, COUNT(CASE WHEN TRAN_STATUS = 4 AND TRAN_RSLT = '0' THEN 1 END) AS cntSucc, COUNT(CASE WHEN TRAN_STATUS = 5 THEN 1 END) AS cntDup, COUNT(CASE WHEN TRAN_STATUS = 4 AND TRAN_RSLT <> '0' THEN 1 END) AS cntSendFail FROM (
SELECT TRAN_STATUS, TRAN_RSLT, B_MSG_KEY FROM ${tableName} WHERE B_MSG_KEY = #{bulkMsgKey}
) T_BROADCAST
